     1→import { Router } from 'express';
     2→import { randomUUID } from 'crypto';
     3→import { getDb } from '../db/database.js';
     4→import { AuthRequest, requireRole } from '../middleware/auth.js';
     5→
     6→export const exercisesRouter = Router();
     7→
     8→// List all exercises with summary stats
     9→exercisesRouter.get('/', (_req, res) => {
    10→  const db = getDb();
    11→  const exercises = db.prepare(`
    12→    SELECT e.id, e.date, e.name, e.notes, e.oe_link_enabled, e.exercise_type, e.simplex_bezirke, e.simplex_bl_codes,
    13→      (SELECT COUNT(DISTINCT operator_id) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0) as participant_count,
    14→      (SELECT COUNT(*) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0 AND readability IS NOT NULL) as report_count
    15→    FROM exercises e ORDER BY e.date ASC
    16→  `).all();
    17→  res.json(exercises);
    18→});
    19→
    20→// Create exercise (admin only)
    21→exercisesRouter.post('/', requireRole('admin'), (req, res) => {
    22→  const { date, name, oe_link_enabled, exercise_type, simplex_bezirke, simplex_bl_codes } = req.body;
    23→  if (!date || !name) {
    24→    res.status(400).json({ error: 'Datum und Name erforderlich' });
    25→    return;
    26→  }
    27→  const db = getDb();
    28→  const id = randomUUID();
    29→  db.prepare('INSERT INTO exercises (id, date, name, oe_link_enabled, exercise_type, simplex_bezirke, simplex_bl_codes) VALUES (?, ?, ?, ?, ?, ?, ?)').run(id, date, name, oe_link_enabled !== undefined ? (oe_link_enabled ? 1 : 0) : 1, exercise_type || 'Krisenkommunikationsübung', simplex_bezirke ? 1 : 0, simplex_bl_codes || null);
    30→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(id);
    31→  res.status(201).json(exercise);
    32→});
    33→
    34→// Get full exercise with reports
    35→exercisesRouter.get('/:id', (req, res) => {
    36→  const db = getDb();
    37→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
    38→  if (!exercise) {
    39→    res.status(404).json({ error: 'Übung nicht gefunden' });
    40→    return;
    41→  }
    42→
    43→  const repeaters = db.prepare(`
    44→    SELECT er.*, r.short_name, r.site_name, r.band, r.callsign as repeater_callsign,
    45→      r.frequency_mhz, r.offset_mhz, r.ctcss_hz, r.burst_hz, r.type, r.is_linked,
    46→      r.bundesland_code, bl.name as bundesland_name
    47→    FROM exercise_repeaters er
    48→    JOIN repeaters r ON r.id = er.repeater_id
    49→    LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code
    50→    WHERE er.exercise_id = ?
    51→    ORDER BY r.bundesland_code, r.sort_order
    52→  `).all(req.params.id);
    53→
    54→  const reports = db.prepare(`
    55→    SELECT sr.*, o.callsign, o.name as operator_name, o.qth as operator_qth, sr.bezirk_code, o.bundesland_code,
    56→      r.short_name as repeater_name, r.bundesland_code as repeater_bundesland_code, r.is_linked as repeater_is_linked,
    57→      ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
    58→    FROM signal_reports sr
    59→    JOIN operators o ON o.id = sr.operator_id
    60→    JOIN repeaters r ON r.id = sr.repeater_id
    61→    LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
    62→    WHERE sr.exercise_id = ?
    63→    ORDER BY r.bundesland_code, o.callsign
    64→  `).all(req.params.id);
    65→
    66→  const attendance = db.prepare(`
    67→    SELECT ea.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code
    68→    FROM exercise_attendance ea
    69→    JOIN operators o ON o.id = ea.operator_id
    70→    WHERE ea.exercise_id = ?
    71→    ORDER BY o.callsign
    72→  `).all(req.params.id);
    73→
    74→  res.json({ ...exercise, repeaters, reports, attendance });
    75→});
    76→
    77→// Update exercise notes/name (admin only)
    78→exercisesRouter.patch('/:id', requireRole('admin'), (req, res) => {
    79→  const db = getDb();
    80→  const { notes, name, oe_link_enabled, organisator, exercise_type, simplex_bezirke, simplex_bl_codes } = req.body;
    81→  const updates: string[] = [];
    82→  const params: any[] = [];
    83→  if (notes !== undefined) { updates.push('notes = ?'); params.push(notes); }
    84→  if (name !== undefined) { updates.push('name = ?'); params.push(name); }
    85→  if (oe_link_enabled !== undefined) { updates.push('oe_link_enabled = ?'); params.push(oe_link_enabled ? 1 : 0); }
    86→  if (organisator !== undefined) { updates.push('organisator = ?'); params.push(organisator || null); }
    87→  if (exercise_type !== undefined) { updates.push('exercise_type = ?'); params.push(exercise_type); }
    88→  if (simplex_bezirke !== undefined) { updates.push('simplex_bezirke = ?'); params.push(simplex_bezirke ? 1 : 0); }
    89→  if (simplex_bl_codes !== undefined) { updates.push('simplex_bl_codes = ?'); params.push(simplex_bl_codes || null); }
    90→  if (updates.length === 0) {
    91→    res.status(400).json({ error: 'Keine Änderungen' });
    92→    return;
    93→  }
    94→  params.push(req.params.id);
    95→  db.prepare(`UPDATE exercises SET ${updates.join(', ')} WHERE id = ?`).run(...params);
    96→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
    97→  res.json(exercise);
    98→});
    99→
   100→// Delete exercise (admin only)
   101→exercisesRouter.delete('/:id', requireRole('admin'), (req, res) => {
   102→  const db = getDb();
   103→  const exercise = db.prepare('SELECT id, name, date FROM exercises WHERE id = ?').get(req.params.id);
   104→  if (!exercise) {
   105→    res.status(404).json({ error: 'Übung nicht gefunden' });
   106→    return;
   107→  }
   108→  const deleteAll = db.transaction(() => {
   109→    db.prepare('DELETE FROM signal_reports WHERE exercise_id = ?').run(req.params.id);
   110→    db.prepare('DELETE FROM exercise_attendance WHERE exercise_id = ?').run(req.params.id);
   111→    db.prepare('DELETE FROM exercise_repeaters WHERE exercise_id = ?').run(req.params.id);
   112→    db.prepare('DELETE FROM exercises WHERE id = ?').run(req.params.id);
   113→  });
   114→  deleteAll();
   115→  res.json({ success: true });
   116→});
   117→
   118→// Get exercise stats
   119→exercisesRouter.get('/:id/stats', (req, res) => {
   120→  const db = getDb();
   121→  const eid = req.params.id;
   122→  const totalParticipants = (db.prepare('SELECT COUNT(DISTINCT operator_id) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0').get(eid) as any)?.c || 0;
   123→  const totalReports = (db.prepare('SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0 AND readability IS NOT NULL').get(eid) as any)?.c || 0;
   124→  const perRepeater = db.prepare(`
   125→    SELECT r.short_name, COUNT(*) as count
   126→    FROM signal_reports sr
   127→    JOIN repeaters r ON r.id = sr.repeater_id
   128→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0 AND sr.readability IS NOT NULL
   129→    GROUP BY sr.repeater_id
   130→    ORDER BY r.sort_order
   131→  `).all(eid);
   132→
   133→  // Bezirk breakdown: participants + reports per bezirk, grouped by bundesland
   134→  const bezirkStats = db.prepare(`
   135→    SELECT COALESCE(bl.name, 'Sonstige') as bundesland,
   136→      COALESCE(bz.bundesland_code, o.bundesland_code, '99') as bundesland_code,
   137→      COALESCE(bl.sort_order, 999) as bl_sort,
   138→      COALESCE(sr.bezirk_code, '??') as bezirk_code,
   139→      COALESCE(bz.name, 'Sonstige') as bezirk_name,
   140→      COALESCE(bz.is_capital, 0) as is_capital,
   141→      COUNT(DISTINCT sr.operator_id) as participants,
   142→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   143→    FROM signal_reports sr
   144→    JOIN operators o ON o.id = sr.operator_id
   145→    LEFT JOIN bezirke bz ON bz.code = sr.bezirk_code
   146→    LEFT JOIN bundeslaender bl ON bl.code = bz.bundesland_code
   147→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   148→    GROUP BY COALESCE(sr.bezirk_code, '??')
   149→    ORDER BY COALESCE(bl.sort_order, 999), COALESCE(sr.bezirk_code, '??')
   150→  `).all(eid);
   151→
   152→  // Bundesland breakdown
   153→  const blStats = db.prepare(`
   154→    SELECT
   155→      COALESCE(bl.name, 'Sonstige') as bundesland,
   156→      o.bundesland_code,
   157→      COUNT(DISTINCT sr.operator_id) as participants,
   158→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   159→    FROM signal_reports sr
   160→    JOIN operators o ON o.id = sr.operator_id
   161→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   162→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   163→    GROUP BY o.bundesland_code
   164→    ORDER BY o.bundesland_code
   165→  `).all(eid);
   166→
   167→  // Participant list: all operators with their report counts
   168→  const participants = db.prepare(`
   169→    SELECT o.callsign, o.name, o.bezirk_code, o.bundesland_code,
   170→      bl.name as bundesland_name,
   171→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as report_count,
   172→      GROUP_CONCAT(DISTINCT sr.suffix) as suffixes
   173→    FROM signal_reports sr
   174→    JOIN operators o ON o.id = sr.operator_id
   175→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   176→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   177→    GROUP BY sr.operator_id
   178→    ORDER BY bl.sort_order, o.bezirk_code, o.callsign
   179→  `).all(eid);
   180→
   181→  res.json({ totalParticipants, totalReports, perRepeater, bezirkStats, blStats, participants });
   182→});
   183→
   184→// Exercise repeaters management
   185→exercisesRouter.get('/:id/repeaters', (req, res) => {
   186→  const db = getDb();
   187→  const repeaters = db.prepare(`
   188→    SELECT er.*, r.short_name, r.site_name, r.band, r.callsign as repeater_callsign,
   189→      r.frequency_mhz, r.offset_mhz, r.ctcss_hz, r.burst_hz, r.type, r.is_linked, r.sort_order,
   190→      r.bundesland_code, bl.name as bundesland_name
   191→    FROM exercise_repeaters er
   192→    JOIN repeaters r ON r.id = er.repeater_id
   193→    LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code
   194→    WHERE er.exercise_id = ?
   195→    ORDER BY r.bundesland_code, r.sort_order
   196→  `).all(req.params.id);
   197→  res.json(repeaters);
   198→});
   199→
   200→exercisesRouter.post('/:id/repeaters', (req, res) => {
   201→  const db = getDb();
   202→  const { repeater_id, operator_callsign, home_repeater } = req.body;
   203→  try {
   204→    db.prepare('INSERT INTO exercise_repeaters (exercise_id, repeater_id, operator_callsign, home_repeater) VALUES (?, ?, ?, ?)').run(req.params.id, repeater_id, operator_callsign || null, home_repeater || null);
   205→    res.status(201).json({ success: true });
   206→  } catch (e: any) {
   207→    if (e.message?.includes('UNIQUE') || e.message?.includes('PRIMARY')) {
   208→      res.status(409).json({ error: 'Umsetzer bereits aktiviert' });
   209→    } else {
   210→      throw e;
   211→    }
   212→  }
   213→});
   214→
   215→exercisesRouter.patch('/:id/repeaters/:rid', (req, res) => {
   216→  const db = getDb();
   217→  const updates: string[] = [];
   218→  const params: any[] = [];
   219→  if (req.body.operator_callsign !== undefined) { updates.push('operator_callsign = ?'); params.push(req.body.operator_callsign || null); }
   220→  if (req.body.home_repeater !== undefined) { updates.push('home_repeater = ?'); params.push(req.body.home_repeater || null); }
   221→  if (updates.length === 0) {
   222→    res.status(400).json({ error: 'Keine Änderungen' });
   223→    return;
   224→  }
   225→  params.push(req.params.id, req.params.rid);
   226→  db.prepare(`UPDATE exercise_repeaters SET ${updates.join(', ')} WHERE exercise_id = ? AND repeater_id = ?`)
   227→    .run(...params);
   228→  res.json({ success: true });
   229→});
   230→
   231→exercisesRouter.delete('/:id/repeaters/:rid', requireRole('admin'), (req, res) => {
   232→  const db = getDb();
   233→  db.prepare('DELETE FROM exercise_repeaters WHERE exercise_id = ? AND repeater_id = ?')
   234→    .run(req.params.id, req.params.rid);
   235→  res.json({ success: true });
   236→});
   237→
   238→// Signal Reports CRUD
   239→exercisesRouter.get('/:id/reports', (req, res) => {
   240→  const db = getDb();
   241→  const reports = db.prepare(`
   242→    SELECT sr.*, o.callsign, o.name as operator_name, o.qth as operator_qth, sr.bezirk_code, o.bundesland_code,
   243→      r.short_name as repeater_name, r.bundesland_code as repeater_bundesland_code, r.is_linked as repeater_is_linked,
   244→      ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
   245→    FROM signal_reports sr
   246→    JOIN operators o ON o.id = sr.operator_id
   247→    JOIN repeaters r ON r.id = sr.repeater_id
   248→    LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
   249→    WHERE sr.exercise_id = ?
   250→    ORDER BY sr.created_at DESC
   251→  `).all(req.params.id);
   252→  res.json(reports);
   253→});
   254→
   255→exercisesRouter.post('/:id/reports', (req, res) => {
   256→  const db = getDb();
   257→  const admin = (req as AuthRequest).admin!;
   258→  const { operator_id, repeater_id, readability, strength, db_over_s9, einstiegspunkt_id, is_op_marker, notes, bezirk_code, suffix } = req.body;
   259→  console.log(`[report] POST exercise=${req.params.id} op=${operator_id} rep=${repeater_id} r=${readability} s=${strength} bz=${bezirk_code || '?'} suffix=${suffix || ''} by=${admin.username}`);
   260→
   261→  if (!operator_id || !repeater_id) {
   262→    console.log('[report] REJECTED: missing operator_id or repeater_id');
   263→    res.status(400).json({ error: 'operator_id und repeater_id erforderlich' });
   264→    return;
   265→  }
   266→
   267→  const insertReportAndAttendance = db.transaction(() => {
   268→    const result = db.prepare(`
   269→      INSERT INTO signal_reports (exercise_id, operator_id, repeater_id, readability, strength, db_over_s9, einstiegspunkt_id, is_op_marker, notes, entered_by, bezirk_code, suffix)
   270→      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
