   310→      CREATE INDEX idx_signal_reports_bezirk ON signal_reports(bezirk_code);
   311→    `);
   312→  }
   313→
   314→  // Migration: backfill operators with null bundesland_code using callsign prefix
   315→  const nullBlOps = db.prepare("SELECT id, callsign FROM operators WHERE bundesland_code IS NULL").all() as { id: number; callsign: string }[];
   316→  if (nullBlOps.length > 0) {
   317→    const updateBl = db.prepare("UPDATE operators SET bundesland_code = ? WHERE id = ?");
   318→    const backfill = db.transaction(() => {
   319→      for (const op of nullBlOps) {
   320→        const code = callsignToCountryCode(op.callsign);
   321→        if (code) updateBl.run(code, op.id);
   322→      }
   323→    });
   324→    backfill();
