  bezirk_code: string | null;
  locator: string | null;
  readability: number | null;
  strength: number | null;
  db_over_s9: string | null;
  repeater_name: string | null;
  notstrom: boolean;
  info: string | null;
  bundesland_section: string;
  matched_repeater_id: number | null;
  is_duplicate: boolean;
  issues: string[];
}

